(* [comment removed for export] *)
Lemma AMBufOwn_aobj : forall LB LF es x sz, AMBufOwn LB es -> In (x, sz) es -> aobj LB LF x (mb_block_size sz).
Proof. intros LB LF es x sz OWN IN. destruct (OWN x sz IN) as [p INb]. eapply aobj_block; [exact INb| lia| lia]. Qed.

Lemma AMBufOwn_fsobj : forall s LB m0 LF es x sz, as_RHEAP H s LB m0 -> AMBufOwn LB es -> In (x, sz) es -> fsobj H LF x (mb_block_size sz).
Proof. intros s LB m0 LF es x sz RH OWN IN. destruct (OWN x sz IN) as [p INb]. eapply (fsobj_block H HH); [exact RH| exact INb]. Qed.

(* [comment removed for export] *)
Lemma AMBraw_ext : forall m m' b es out insz op oe,
  AMBraw m b es out insz op oe ->
  (forall A cs, rw_cells asegs m A cs ->
     (b <= A /\ A + Z.of_nat (cells_size cs) <= b + 64)
     \/ (exists x sz, In (x, sz) es /\ x <= A /\ A + Z.of_nat (cells_size cs) <= x + mb_block_size sz) ->
     rw_cells asegs m' A cs) ->
  (forall x sz, In (x, sz) es -> addressable m x (mb_block_size sz) -> addressable m' x (mb_block_size sz)) ->
  (accessible m b 64 -> accessible m' b 64) ->
  AMBraw m' b es out insz op oe.
Proof.
  intros m m' b es out insz op oe (ls & H0 & H1 & DL & LC & EL & AOK & SH & AB) KC KA KB.
  exists ls. split; [apply (KC _ _ H0); left; cbn; lia|]. split; [apply (KC _ _ H1); left; cbn; lia|].
  split; [exact DL|]. split.
  { intros a n La. destruct (LC a n La) as [WF C]. split; [exact WF|]. apply (KC _ _ C). rewrite LNodeCells_size.
    destruct (mb_lnode_cases _ _ _ _ _ DL AOK La) as [->|(sz & IN)]; [left; lia| right].
    destruct (mb_addr_ok_elem _ _ _ _ AOK IN) as (_ & _ & S0 & R1 & _). exists a, sz. split; [exact IN| lia]. }
  split.
  { intros x sz IN. destruct (EL x sz IN) as [junk C]. exists junk. apply (KC _ _ C). right. exists x, sz.
    destruct (mb_addr_ok_elem _ _ _ _ AOK IN) as (_ & _ & S0 & R1 & _).
    cbn [cells_size csize]. rewrite Nat.add_0_r, Nat2Z.inj_add, Z2Nat.id by lia. split; [exact IN| lia]. }
  split; [exact AOK|]. split; [intros x sz IN; exact (KA x sz IN (SH x sz IN))| exact (KB AB)].
Qed.

(* [comment removed for export] *)
Lemma AMBraw_apres : forall s LB m0 LF m1 SP m m' b es out insz op oe,
  as_RHEAP H s LB m0 -> as_RFS H LF m1 -> aobj LB LF b 64 -> AMBufOwn LB es ->
  AMBraw m b es out insz op oe -> apres H LB SP m m' -> AMBraw m' b es out insz op oe.
Proof.
  intros s LB m0 LF m1 SP m m' b es out insz op oe RH RF AOB OWN R AP.
  eapply AMBraw_ext; [exact R| | |].
  - intros A cs C [[K1 K2]|(x & sz & IN & K1 & K2)].
    + eapply (apres_rw_cells H); [exact AP| exact C|]. eapply (aobj_client H HH); [exact RH| exact RF| eapply aobj_sub; [exact AOB| exact K1| exact K2]].
    + destruct (OWN x sz IN) as [p INb]. eapply (apres_rw_cells H); [exact AP| exact C|]. eapply aclient_range_block; [exact INb| exact K1| exact K2].
  - intros x sz IN AD. destruct (OWN x sz IN) as [p INb]. eapply (apres_addressable H); [exact AP| exact AD| exact INb].
  - intros AC. eapply (aobj_apres_accessible H HH); [exact RH| exact RF| exact AOB| exact AP| exact AC| lia| lia].
Qed.

(* [comment removed for export] *)
Lemma AMBraw_xpres : forall s LB m0 LF m1 SP X XS m m' b es out insz op oe,
  as_RHEAP H s LB m0 -> as_RFS H LF m1 -> aobj LB LF b 64 -> AMBufOwn LB es ->
  AMBraw m b es out insz op oe -> xpres H LB SP (X ++ XS) m m' -> Forall noshadow X -> Forall (fs_scratch H LF) XS ->
  Forall (fun iv : Z * Z => b + 64 <= fst iv \/ snd iv <= b) X ->
  (forall x sz, In (x, sz) es -> Forall (fun iv : Z * Z => x + mb_block_size sz <= fst iv \/ snd iv <= x) X) ->
  AMBraw m' b es out insz op oe.
Proof.
  intros s LB m0 LF m1 SP X XS m m' b es out insz op oe RH RF AOB OWN R XP NSX FS XB XE.
  assert (SUBF : forall (O n a k : Z), Forall (fun iv : Z * Z => O + n <= fst iv \/ snd iv <= O) X -> O <= a -> a + k <= O + n ->
            Forall (fun iv : Z * Z => a + k <= fst iv \/ snd iv <= a) X).
  { intros O n a k FO K1 K2. eapply Forall_impl; [| exact FO]. intros [l h] K. cbn in *. lia. }
  eapply AMBraw_ext; [exact R| | |].
  - intros A cs C [[K1 K2]|(x & sz & IN & K1 & K2)].
    + eapply (xpres_rw_cells H); [exact XP| exact C|].
      eapply (xclient_range_aobj H HH); [exact RH| exact RF| eapply aobj_sub; [exact AOB| exact K1| exact K2]| lia| | exact FS].
      eapply (SUBF b 64); [exact XB| exact K1| exact K2].
    + eapply (xpres_rw_cells H); [exact XP| exact C|].
      eapply (xclient_range_aobj H HH); [exact RH| exact RF| eapply aobj_sub; [exact (AMBufOwn_aobj _ LF _ _ _ OWN IN)| exact K1| exact K2]| lia| | exact FS].
      eapply (SUBF x (mb_block_size sz)); [exact (XE x sz IN)| exact K1| exact K2].
  - intros x sz IN AD. destruct (OWN x sz IN) as [p INb].
    eapply (blk_xpres_addressable H HH); [exact RH| exact RF| exact INb| exact XP| exact NSX| exact FS| exact AD].
  - intros AC. eapply (aobj_xpres_accessible H HH); [exact RH| exact RF| exact AOB| lia| exact XP| exact NSX| exact FS| exact AC| lia| lia].
Qed.

(* [comment removed for export] *)
Lemma AMBraw_transport_scr : forall s LB m0 LF m1 X XS m m' b es out insz op oe,
  as_RHEAP H s LB m0 -> as_RFS H LF m1 -> aobj LB LF b 64 -> AMBufOwn LB es ->
  AMBraw m b es out insz op oe -> munch (X ++ XS) m m' -> wmono asegs m m' -> Forall awin X -> Forall (fs_scratch H LF) XS ->
  disjoint_from X b 64 -> (forall x sz, In (x, sz) es -> disjoint_from X x (mb_block_size sz)) ->
  AMBraw m' b es out insz op oe.
Proof.
  intros s LB m0 LF m1 X XS m m' b es out insz op oe RH RF AOB OWN R MU WM FX FS DB DE.
  pose proof (aobj_fsobj H HH _ _ _ _ _ _ RH AOB) as FOB. pose proof (aobj_aapp H HH _ _ _ _ _ _ _ RH RF AOB) as APB.
  pose proof (AMBraw_addr_ok _ _ _ _ _ _ _ R) as AOK.
  eapply AMBraw_ext; [exact R| | |].
  - intros A cs C [[K1 K2]|(x & sz & IN & K1 & K2)].
    + eapply (rw_cells_transport_scr H HH LF m1 X XS m m'); [exact RF| eapply fsobj_sub; [exact FOB| exact K1| exact K2]
        | eapply aapp_sub; [exact APB| exact K1| exact K2] | exact C| exact MU| exact WM| | exact FS].
      eapply disjoint_from_sub; [exact DB| exact K1| exact K2].
    + pose proof (AMBufOwn_fsobj _ _ _ LF _ _ _ RH OWN IN) as FOE. destruct (mb_addr_ok_elem _ _ _ _ AOK IN) as (_ & _ & _ & _ & _ & _ & _ & _ & APE & _).
      eapply (rw_cells_transport_scr H HH LF m1 X XS m m'); [exact RF| eapply fsobj_sub; [exact FOE| exact K1| exact K2]
        | eapply aapp_sub; [exact APE| exact K1| exact K2] | exact C| exact MU| exact WM| | exact FS].
      eapply disjoint_from_sub; [exact (DE x sz IN)| exact K1| exact K2].
  - intros x sz IN AD. destruct (mb_addr_ok_elem _ _ _ _ AOK IN) as (_ & _ & _ & _ & _ & _ & _ & _ & APE & _).
    eapply (addressable_transport_scr H HH LF m1 X XS m m'); [exact RF| exact (AMBufOwn_fsobj _ _ _ LF _ _ _ RH OWN IN)| exact APE| exact AD| exact MU| exact WM| exact FX| exact FS].
  - intros AC. eapply (accessible_transport_scr H HH LF m1 X XS m m'); [exact RF| exact FOB| exact APB| lia| exact AC| exact MU| exact FX| exact FS].
Qed.

(* [comment removed for export] *)
Lemma AMBraw_fs_call : forall s LB m0 LF k ff fp m1 m2 b es out insz op oe slo shi',
  as_RHEAP H s LB m0 -> as_RFS H LF m1 -> fresh_frame H LF k ff fp -> aceil <= slo ->
  aobj LB LF b 64 -> AMBufOwn LB es ->
  AMBraw m1 b es out insz op oe -> munch (fs_W5 H slo shi' fp ff k) m1 m2 -> wmono asegs m1 m2 ->
  AMBraw m2 b es out insz op oe.
Proof.
  intros s LB m0 LF k ff fp m1 m2 b es out insz op oe slo shi' RH RF FF CEIL AOB OWN R MU WM.
  pose proof (aobj_fsobj H HH _ _ _ _ _ _ RH AOB) as FOB. pose proof (aobj_aapp H HH _ _ _ _ _ _ _ RH RF AOB) as APB.
  pose proof (aobj_range H HH _ _ _ _ _ _ _ RH RF AOB) as [OB1 OB2].
  pose proof (AMBraw_addr_ok _ _ _ _ _ _ _ R) as AOK. pose proof aceil_facts as (AF1 & _). pose proof (mb_addr_ok_obj _ _ AOK) as (_ & _ & OB3 & OB4 & _).
  eapply AMBraw_ext; [exact R| | |].
  - intros A cs C [[K1 K2]|(x & sz & IN & K1 & K2)].
    + eapply rw_cells_transport; [exact C| exact MU| exact WM|]. unfold fs_W5.
      eapply disjoint_from_sub; [| exact K1| exact K2].
      eapply (fsobj_disjoint H HH); [exact RF| exact FOB| exact FF| lia| lia| lia| exact APB| left; lia].
    + destruct (mb_addr_ok_elem _ _ _ _ AOK IN) as (X0 & _ & S0 & R1 & _ & _ & XH & XH2 & APE & _).
      eapply rw_cells_transport; [exact C| exact MU| exact WM|]. unfold fs_W5.
      eapply disjoint_from_sub; [| exact K1| exact K2].
      eapply (fsobj_disjoint H HH); [exact RF| exact (AMBufOwn_fsobj _ _ _ LF _ _ _ RH OWN IN)| exact FF| lia| lia| lia| exact APE| left; lia].
  - intros x sz IN AD. destruct (mb_addr_ok_elem _ _ _ _ AOK IN) as (X0 & _ & S0 & R1 & _ & _ & XH & XH2 & APE & _).
    eapply addressable_transport; [exact AD| exact MU| exact WM|]. unfold fs_W5.
    eapply (fsobj_disjoint_sh H HH); [exact RF| exact (AMBufOwn_fsobj _ _ _ LF _ _ _ RH OWN IN)| exact FF| lia| lia| lia| exact CEIL].
  - intros AC. eapply (fs_acc_call H HH); [exact RF| exact FF| exact CEIL| exact AC| exact APB| lia| exact FOB| exact MU].
Qed.

